const raw = $json;
const fail = () => { throw new Error('CONTRACT_INVALID'); };
const expectedRoot = ['appointments', 'cutoff_at', 'dispatch', 'generated_at', 'range', 'report_type', 'schema_version', 'timezone', 'total'];
const keys = raw && typeof raw === 'object' && !Array.isArray(raw) ? Object.keys(raw).sort() : [];
if (JSON.stringify(keys) !== JSON.stringify(expectedRoot.slice().sort())) fail();
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (value) => { if (typeof value !== 'string' || !datePattern.test(value)) return false; const parsed = new Date(value + 'T00:00:00Z'); return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value; };
if (raw.schema_version !== 1 || raw.timezone !== 'America/Guatemala' || raw.report_type !== 'weekly_missed_appointments') fail();
if (!raw.range || Object.keys(raw.range).sort().join(',') !== 'from,to' || !realDate(raw.range.from) || !realDate(raw.range.to)) fail();
const from = Date.parse(raw.range.from + 'T00:00:00Z');
const to = Date.parse(raw.range.to + 'T00:00:00Z');
if (to - from !== 6 * 86400000 || new Date(from).getUTCDay() !== 1 || new Date(to).getUTCDay() !== 0) fail();
if (typeof raw.generated_at !== 'string' || Number.isNaN(Date.parse(raw.generated_at)) || typeof raw.cutoff_at !== 'string' || Number.isNaN(Date.parse(raw.cutoff_at))) fail();
if (!Number.isSafeInteger(raw.total) || raw.total < 0 || raw.total > 10000 || !Array.isArray(raw.appointments)) fail();
if (!raw.dispatch || typeof raw.dispatch !== 'object' || Array.isArray(raw.dispatch)) fail();
const status = raw.dispatch.status;
if (!['ready', 'no_results', 'already_processed'].includes(status)) fail();
const dispatchKeys = Object.keys(raw.dispatch).sort();
if (status === 'ready') {
  if (dispatchKeys.join(',') !== 'status,token' || typeof raw.dispatch.token !== 'string' || !/^[A-Za-z0-9_-]{43}$/.test(raw.dispatch.token) || raw.total < 1 || raw.appointments.length !== raw.total) fail();
} else if (dispatchKeys.join(',') !== 'status' || raw.total !== 0 || raw.appointments.length !== 0) fail();
const cleanAppointments = raw.appointments.map((appointment) => {
  const appointmentKeys = appointment && typeof appointment === 'object' && !Array.isArray(appointment) ? Object.keys(appointment).sort() : [];
  if (JSON.stringify(appointmentKeys) !== JSON.stringify(['community', 'date', 'first_name', 'last_name', 'phone'])) fail();
  if (!realDate(appointment.date) || appointment.date < raw.range.from || appointment.date > raw.range.to) fail();
  for (const [key, max] of [['first_name', 80], ['last_name', 80], ['phone', 32], ['community', 120]]) { if (typeof appointment[key] !== 'string' || appointment[key].length > max || /[\u0000-\u001f\u007f]/.test(appointment[key])) fail(); }
  return { date: appointment.date, first_name: appointment.first_name, last_name: appointment.last_name, phone: appointment.phone, community: appointment.community };
});
return [{ json: { range: { from: raw.range.from, to: raw.range.to }, total: raw.total, appointments: cleanAppointments, dispatch_token: status === 'ready' ? raw.dispatch.token : null, should_send: status === 'ready' } }];

const raw = $json;
if (!raw.should_send || !Number.isSafeInteger(raw.total) || raw.total < 1 || !Array.isArray(raw.appointments) || raw.appointments.length !== raw.total || typeof raw.dispatch_token !== 'string') throw new Error('CONTRACT_INVALID');
const escapeHtml = (value) => String(value || 'No registrado').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const formatDate = (value) => value.split('-').reverse().join('-');
const rows = raw.appointments.map((appointment) => '<tr><td style="padding:7px;border-bottom:1px solid #e5e7eb;white-space:nowrap">' + escapeHtml(formatDate(appointment.date)) + '</td><td style="padding:7px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.first_name) + ' ' + escapeHtml(appointment.last_name) + '</td><td style="padding:7px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.phone) + '</td><td style="padding:7px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.community) + '</td></tr>').join('');
const fromLabel = formatDate(raw.range.from);
const toLabel = formatDate(raw.range.to);
const subject = 'CAP Prenatal | Seguimiento semanal de inasistencias | ' + fromLabel + ' al ' + toLabel;
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.5"><h2 style="color:#7c3aed;margin-bottom:8px">Seguimiento de inasistencias</h2><p>Buen día.</p><p>Se identificaron citas programadas que requieren seguimiento por no contar con un control prenatal registrado posteriormente.</p><p><strong>Periodo revisado:</strong> ' + escapeHtml(fromLabel) + ' al ' + escapeHtml(toLabel) + '<br><strong>Total de inasistencias detectadas:</strong> ' + raw.total + '</p><table style="border-collapse:collapse;width:100%;max-width:820px;font-size:14px"><thead><tr style="background:#f3f4f6"><th style="padding:7px;text-align:left">Fecha de cita</th><th style="padding:7px;text-align:left">Paciente</th><th style="padding:7px;text-align:left">Teléfono</th><th style="padding:7px;text-align:left">Comunidad</th></tr></thead><tbody>' + rows + '</tbody></table><p style="font-size:12px;color:#6b7280">Se incluye únicamente la información mínima necesaria para facilitar el seguimiento por el personal autorizado. Este es un mensaje automático. No responda a este correo.</p></div>';
return [{ json: { subject, html, dispatch_token: raw.dispatch_token } }];
